import os, pty, sys, time, select, subprocess

def run(cmd, cwd, inputs, timeout=20):
    pid, fd = pty.fork()
    if pid == 0:
        os.chdir(cwd)
        env = dict(os.environ)
        env["GIT_CONFIG_GLOBAL"] = "/dev/null"
        env["TERM"] = "xterm-256color"
        os.execvpe(cmd[0], cmd, env)
    out = b""
    start = time.time()
    idx = 0
    last = time.time()
    while time.time() - start < timeout:
        r, _, _ = select.select([fd], [], [], 0.5)
        if r:
            try:
                d = os.read(fd, 4096)
            except OSError:
                break
            if not d:
                break
            out += d
            last = time.time()
        elif idx < len(inputs) and time.time() - last > 0.7:
            os.write(fd, inputs[idx].encode())
            idx += 1
            last = time.time()
        try:
            p, status = os.waitpid(pid, os.WNOHANG)
            if p:
                break
        except ChildProcessError:
            break
    return out.decode(errors="replace")

if __name__ == "__main__":
    cwd = sys.argv[1]
    inputs = sys.argv[2].split("|") if sys.argv[2] else []
    inputs = [i.replace("\\n", "\n").replace("\\x1b[B", "\x1b[B").replace("\\x20", " ") for i in inputs]
    print(run(sys.argv[3:], cwd, inputs))

